logs\"\r\n    ];\r\n\r\n    foreach($dirs as $dir){\r\n        if(!is_dir($base . $dir)){\r\n            mkdir($base . $dir, 0777, true);\r\n        }\r\n    }\r\n\r\n    initializeCaseFiles($case_id);\r\n}\r\n\r\nfunction initializeCaseFiles($case_id){\r\n\r\n    $base = getCasePath($case_id);\r\n\r\n    $files = [\r\n        \"/case.json\" => [],\r\n        \"/network.json\" => [\"nodes\"=>[], \"edges\"=>[]],\r\n        \"/strategy_plan.json\" => [],\r\n        \"/memory/snapshots.json\" => [],\r\n        \"/tasks/queue.json\" => [],\r\n        \"/tasks/history.json\" => [],\r\n        \"/goals/active.json\" => [],\r\n        \"/goals/proposals.json\" => []\r\n    ];\r\n\r\n    foreach($files as $file => $default){\r\n\r\n        $full = $base . $file;\r\n\r\n        if(!file_exists($full)){\r\n            file_put_contents(\r\n                $full,\r\n                json_encode($default, JSON_PRETTY_PRINT)\r\n            );\r\n        }\r\n    }\r\n}\r\n\r\n/*\r\n================================================\r\nGRAPH LOAD / SAVE\r\n================================================\r\n*/\r\n\r\nfunction loadGraph($case_id){\r\n\r\n    $path = getCasePath($case_id) . \"/network.json\";\r\n\r\n    return json_decode(file_get_contents($path), true);\r\n}\r\n\r\nfunction saveGraph($case_id, $graph){\r\n\r\n    $path = getCasePath($case_id) . \"/network.json\";\r\n\r\n    file_put_contents($path, json_encode($graph, JSON_PRETTY_PRINT));\r\n}\r\n\r\n/*\r\n================================================\r\nTASK QUEUE\r\n================================================\r\n*/\r\n\r\nfunction enqueueTask($case_id, $task){\r\n\r\n    $path = getCasePath($case_id) . \"/tasks/queue.json\";\r\n\r\n    $queue = json_decode(file_get_contents($path), true);\r\n\r\n    $queue[] = $task;\r\n\r\n    file_put_contents($path, json_encode($queue, JSON_PRETTY_PRINT));\r\n}\r\n\r\nfunction loadQueue($case_id){\r\n\r\n    $path = getCasePath($case_id) . \"/tasks/queue.json\";\r\n\r\n    return json_decode(file_get_contents($path), true);\r\n}\r\n\r\nfunction saveQueue($case_id, $queue){\r\n\r\n    $path = getCasePath($case_id) . \"/tasks/queue.json\";\r\n\r\n    file_put_contents($path, json_encode($queue, JSON_PRETTY_PRINT));\r\n}\r\n\r\n/*\r\n================================================\r\nGOALS\r\n================================================\r\n*/\r\n\r\nfunction loadGoals($case_id){\r\n\r\n    $path = getCasePath($case_id) . \"/goals/active.json\";\r\n\r\n    return json_decode(file_get_contents($path), true);\r\n}\r\n\r\nfunction saveGoals($case_id, $goals){\r\n\r\n    $path = getCasePath($case_id) . \"/goals/active.json\";\r\n\r\n    file_put_contents($path, json_encode($goals, JSON_PRETTY_PRINT));\r\n}\r\n\r\n/*\r\n================================================\r\nMEMORY SNAPSHOTS\r\n================================================\r\n*/\r\n\r\nfunction writeSnapshot($case_id, $snapshot){\r\n\r\n    $path = getCasePath($case_id) . \"/memory/snapshots.json\";\r\n\r\n    $data = json_decode(file_get_contents($path), true);\r\n\r\n    $data[] = $snapshot;\r\n\r\n    file_put_contents($path, json_encode($data, JSON_PRETTY_PRINT));\r\n}\r\n📁 STEP 2 — UPDATE WORKER (FULL FILE REPLACEMENT)\r\nFILE:\r\n/www/www/commandcenter/cli/worker.php\r\nFULL CONTENT:\r\n<?php\r\n\r\nrequire_once __DIR__ . \'/../engine/case_manager.php\';\r\n\r\n/*\r\n================================================\r\nLEGAISEE WORKER v1.0 (CASE-AWARE)\r\n================================================\r\n*/\r\n\r\n$case_id = 1; // CHANGE LATER TO DYNAMIC\r\n\r\nensureCaseStructure($case_id);\r\n\r\n/*\r\n================================================\r\nLOAD SYSTEM STATE\r\n================================================\r\n*/\r\n\r\n$graph = loadGraph($case_id);\r\n$queue = loadQueue($case_id);\r\n\r\n/*\r\n================================================\r\nPROCESS TASKS\r\n================================================\r\n*/\r\n\r\n$newQueue = [];\r\n\r\nforeach($queue as $task){\r\n\r\n    if(($task[\'type\'] ?? \'\') === \'add_node\'){\r\n\r\n        $graph[\'nodes\'][] = [\r\n            \"id\" => uniqid(\"n_\"),\r\n            \"type\" => \"signal\",\r\n            \"strength\" => 100,\r\n            \"content\" => $task[\'content\'] ?? \'\',\r\n            \"created_at\" => date(\"c\")\r\n        ];\r\n    }\r\n\r\n    else {\r\n        // unknown task, keep it\r\n        $newQueue[] = $task;\r\n    }\r\n}\r\n\r\n/*\r\n================================================\r\nSAVE STATE\r\n================================================\r\n*/\r\n\r\nsaveGraph($case_id, $graph);\r\nsaveQueue($case_id, $newQueue);\r\n\r\n/*\r\n================================================\r\nSNAPSHOT MEMORY\r\n================================================\r\n*/\r\n\r\nwriteSnapshot($case_id, [\r\n    \"time\" => date(\"c\"),\r\n    \"node_count\" => count($graph[\'nodes\']),\r\n    \"queue_size\" => count($newQueue)\r\n]);\r\n\r\necho json_encode([\r\n    \"status\" => \"worker_complete\",\r\n    \"nodes\" => count($graph[\'nodes\'])\r\n]);\r\n📁 STEP 3 — FIX YOUR INGEST API (FULL REPLACEMENT)\r\nFILE:\r\n/www/www/commandcenter/api/v8/network_add_node.php\r\nFULL CONTENT:\r\n<?php\r\n\r\nrequire_once __DIR__ . \'/../../engine/case_manager.php\';\r\n\r\nheader(\'Content-Type: application/json\');\r\n\r\n$case_id = $_POST[\'case_id\'] ?? 1;\r\n$content = $_POST[\'content\'] ?? \'\';\r\n\r\nif(empty($content)){\r\n    echo json_encode([\"error\"=>\"missing content\"]);\r\n    exit;\r\n}\r\n\r\nensureCaseStructure($case_id);\r\n\r\nenqueueTask($case_id, [\r\n    \"type\" => \"add_node\",\r\n    \"content\" => $content,\r\n    \"time\" => date(\"c\")\r\n]);\r\n\r\necho json_encode([\r\n    \"status\" => \"queued\"\r\n]);\r\n📁 STEP 4 — UPDATE BRAIN UI FETCH (CRITICAL FIX)\r\nFILE:\r\n/www/www/commandcenter/Brain.php\r\nREPLACE ONLY THIS LINE INSIDE ingest():\r\nOLD:\r\nbody: \"network_id=net_case_\" + CASE_ID + \"&content=\" +\r\nNEW:\