\nfallback rendering systems\r\n\r\nalternative layout systems\r\n\r\n🧱 STEP 3 — STANDARD PAGE TEMPLATE (ALL PAGES MUST MATCH)\r\nEvery page MUST look like this:\r\n\r\n📁 index.php\r\n<?php\r\nrequire_once __DIR__ . \"/bootstrap.php\";\r\n\r\n$pageTitle = \"Dashboard\";\r\n$pageDesc  = \"System Hub\";\r\n\r\n$contentFile = __DIR__ . \"/modules/dashboard_module.php\";\r\n\r\ninclude __DIR__ . \"/shell.php\";\r\n📁 search.php\r\n<?php\r\nrequire_once __DIR__ . \"/bootstrap.php\";\r\n\r\n$pageTitle = \"Search Intelligence\";\r\n$pageDesc  = \"Query system nodes\";\r\n\r\n$contentFile = __DIR__ . \"/modules/search_module.php\";\r\n\r\ninclude __DIR__ . \"/shell.php\";\r\n📁 ingest.php\r\n<?php\r\nrequire_once __DIR__ . \"/bootstrap.php\";\r\n\r\n$pageTitle = \"Ingest Node\";\r\n$pageDesc  = \"Create intelligence entries\";\r\n\r\nif ($_SERVER[\'REQUEST_METHOD\'] === \'POST\') {\r\n\r\n    $stmt = $pdo->prepare(\"\r\n        INSERT INTO page (title, project, platform, type)\r\n        VALUES (?, ?, ?, ?)\r\n    \");\r\n\r\n    $stmt->execute([\r\n        $_POST[\'title\'] ?? \'\',\r\n        $_POST[\'project\'] ?? \'\',\r\n        $_POST[\'platform\'] ?? \'\',\r\n        $_POST[\'type\'] ?? \'\'\r\n    ]);\r\n\r\n    $id = $pdo->lastInsertId();\r\n\r\n    $stmt = $pdo->prepare(\"\r\n        INSERT INTO page_content (page_id, content)\r\n        VALUES (?, ?)\r\n    \");\r\n\r\n    $stmt->execute([\r\n        $id,\r\n        $_POST[\'content\'] ?? \'\'\r\n    ]);\r\n\r\n    header(\"Location: ingest.php\");\r\n    exit;\r\n}\r\n\r\n$contentFile = __DIR__ . \"/modules/ingest_module.php\";\r\n\r\ninclude __DIR__ . \"/shell.php\";\r\n📁 graph.php\r\n<?php\r\nrequire_once __DIR__ . \"/bootstrap.php\";\r\n\r\n$pageTitle = \"Graph View\";\r\n$pageDesc  = \"Node relationships\";\r\n\r\n$contentFile = __DIR__ . \"/modules/graph_module.php\";\r\n\r\ninclude __DIR__ . \"/shell.php\";\r\n📁 files.php\r\n<?php\r\nrequire_once __DIR__ . \"/bootstrap.php\";\r\n\r\n$pageTitle = \"Files\";\r